-- 추가 예문 작문 방식을 '타이핑'에서 '단어 칩 순서 맞추기'로 전환한다. (LAN-229)
-- practice_examples_payload의 예문마다 sentenceWords(정답 순서 단어 배열)와
-- sentenceWordChoices(정답+오답 단어를 섞은 선택지 배열) 키를 추가한 payload로 교체한다.
-- jsonb 캐스팅을 쓰므로 PostgreSQL 전용 폴더에 둔다. (H2 테스트 DB는 이 폴더를 읽지 않는다)
-- develop DB는 수동 UPDATE로 먼저 교정하므로, 이미 sentenceWords 키가 있는 행은 가드로 건너뛴다.
-- 이 backfill 없이 배포되면 단어 배열이 필수 키라 추가 예문 API가 404를 반환하므로 반드시 같은 릴리스로 나가야 한다.

UPDATE writing_expression
SET practice_examples_payload = '[{"imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1/practice-examples/25e16edf-e702-4141-b303-b9bc1a73b891.png", "sentenceText": "There''s nothing like a cold beer on a hot day.", "highlightingPart": "There''s nothing like", "practiceQuestion": "Want a cold beer? It''s so hot.", "sentenceTranslation": "더운 날엔 시원한 맥주만 한 게 없지.", "practiceQuestionTranslation": "시원한 맥주 마실래? 너무 덥다.", "sentenceWords": ["There''s", "nothing", "like", "a", "cold", "beer", "on", "a", "hot", "day"], "sentenceWordChoices": ["beats", "a", "cold", "nothing", "better", "beer", "than", "day", "like", "There''s", "hot", "a", "on"]}, {"imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1/practice-examples/d72773a0-98d3-4781-9c1a-65ff7b3e1e15.png", "sentenceText": "There''s nothing like mom''s cooking.", "highlightingPart": "There''s nothing like", "practiceQuestion": "What do you miss most about being away from home?", "sentenceTranslation": "엄마 밥만 한 게 없어.", "practiceQuestionTranslation": "집 떠나 있으니까 뭐가 제일 그리워?", "sentenceWords": ["There''s", "nothing", "like", "mom''s", "cooking"], "sentenceWordChoices": ["than", "like", "nothing", "There''s", "beats", "cooking", "mom''s", "better"]}, {"imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1/practice-examples/7b80223d-4373-413e-8675-68d809e60e14.png", "sentenceText": "There''s nothing like a good night''s sleep.", "highlightingPart": "There''s nothing like", "practiceQuestion": "I''m so exhausted today.", "sentenceTranslation": "푹 자는 것만큼 좋은 게 없어.", "practiceQuestionTranslation": "나 오늘 완전 피곤해.", "sentenceWords": ["There''s", "nothing", "like", "a", "good", "night''s", "sleep"], "sentenceWordChoices": ["a", "good", "than", "like", "night''s", "better", "beats", "sleep", "There''s", "nothing"]}, {"imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1/practice-examples/84a42e0b-cad0-484c-b71b-028a44fdb9b0.png", "sentenceText": "There''s nothing like traveling with friends.", "highlightingPart": "There''s nothing like", "practiceQuestion": "What''s your favorite way to spend a vacation?", "sentenceTranslation": "친구들이랑 여행하는 것만 한 게 없지.", "practiceQuestionTranslation": "휴가 때 뭐 하는 게 제일 좋아?", "sentenceWords": ["There''s", "nothing", "like", "traveling", "with", "friends"], "sentenceWordChoices": ["traveling", "There''s", "beats", "nothing", "better", "than", "like", "friends", "with"]}]'::jsonb,
    updated_at = now()
WHERE id = 1
  AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(practice_examples_payload) AS e
      WHERE e ? 'sentenceWords'
  );

